; Phoenix 80486 system BIOS (F000 segment)
; segment F000, 65536 (0x10000) bytes; generated by tools/romdis.py - labels are best guesses
;

phoenix_copyright_1:
        ; Copyright banner padding to 0x0100
        ; [data] Phoenix copyright banner (space padded)
        ; [data] string
F000:0000                              db  'Copyright 1985-1992 Phoenix Technologies Ltd.                                                                                                                                                                                                                   '

setup_far_entry:
        ; Far-callable SETUP utility entry (jmp 1934). Called by PhoenixMISER (E800:061D lcall F000:0100) and by the INT 09h Ctrl+Alt+S hotkey path.
F000:0100 E9 31 18                     jmp     setup_main

setup_key_maps:
        ; Four NUL-terminated (scancode, handler) lists used by the SETUP key dispatcher: 2Bh/20h/4Dh/4Eh/39h -> setup_key_next_value (269A), 2Dh/4Bh/4Ah -> setup_key_prev_value (2730), 1Bh/01h Esc -> setup_key_escape (1FF9), 50h Down -> 25E8, 48h Up -> 25EF, 51h PgDn -> 2668, 49h PgUp -> 2681, 42h F8 -> 3AFA, 0Eh Backspace -> 2767, 08h -> 2355.
        ; [data] setup_key_maps
F000:0103                              db  2B 9A 26 20 9A                                  ; +.& .
F000:0108                              db  '&-0'''
F000:010C                              db  08 55 23 1B F9 1F 00 4D 9A 26 50 E8             ; .U#....M.&P.
F000:0118                              db  '%K0''H'
F000:011D                              db  EF                                              ; .
F000:011E                              db  '%Qh&I'
F000:0123                              db  81 26 42 FA 3A 00 4E 9A                         ; .&B.:.N.
F000:012B                              db  '&J0''9'
F000:0130                              db  9A 26 0E 67 27 01 F9 1F 00 4D 9A 26 50 E8       ; .&.g'....M.&P.
F000:013E                              db  '%K0''H'
F000:0143                              db  EF                                              ; .
F000:0144                              db  '%Qg''Ig''',00h

